/**
 * Names the rest of the app uses for the backend's schemas.
 *
 * Role: the one bridge between the generated schema.gen.ts (from openapi/openapi.json) and the app.
 * Used by: lib/api errors and form-errors, providers/auth, features/profile, features/users,
 *   routes/RequirePermission.tsx, routes/router.tsx, components/layout/AppShell.tsx.
 * Depends on: components['schemas'] from ./schema.gen (generated by `npm run api:types`).
 * Key invariants: the only importer of schema.gen.ts (template_web D-005); PATCH bodies use
 *   WithoutNulls because the backend rejects explicit nulls although its schema allows them; types
 *   only, no runtime code.
 */
import type { components } from './schema.gen';

type Schemas = components['schemas'];

/**
 * The PATCH schemas allow null in every field, but the backend rejects explicit
 * nulls: a field is either sent with a value or left out.
 */
type WithoutNulls<T> = { [K in keyof T]?: Exclude<T[K], null> };

export type Token = Schemas['TokenResponse'];
export type Me = Schemas['CurrentUserResponse'];
export type Permission = Schemas['Permission'];
export type RoleName = Schemas['RoleName'];
export type Role = Schemas['RoleDetails'];

export type User = Schemas['UserDetails'];
export type UserPage = Schemas['UserPage'];
export type UserCreate = Schemas['UserCreate'];
export type UserAdminUpdate = WithoutNulls<Schemas['UserAdminUpdate']>;
export type UserSelfUpdate = WithoutNulls<Schemas['UserSelfUpdate']>;
export type PasswordChange = Schemas['PasswordChange'];

export type ProblemDetails = Schemas['ProblemDetails'];
export type FieldError = Schemas['FieldError'];
export type ErrorCode = Schemas['ErrorCode'];
